526	/* Stop the engine without HAL_DMA_Abort / FreeChannel / irq_detach. */
527	static void sifli_uart_dma_stop(struct sifli_uart *uart)
528	{
529	    DMA_HandleTypeDef *hdma = uart->handle.hdmarx;
530	
531	    if (uart->handle.Instance != NULL)
532	    {
533	        CLEAR_BIT(uart->handle.Instance->CR3, USART_CR3_DMAR);
534	    }
535	
536	    if (hdma != NULL && hdma->Instance != NULL)
537	    {
538	        __HAL_DMA_DISABLE(hdma);
539	        if (hdma->DmaBaseAddress != NULL)
540	        {
541	            hdma->DmaBaseAddress->IFCR =
542	                (DMA_ISR_GIF1 << (hdma->ChannelIndex & 0x1cU));
543	        }
544	
545	        hdma->State = HAL_DMA_STATE_READY;
546	        hdma->Lock = HAL_UNLOCKED;
547	        hdma->ErrorCode = HAL_DMA_ERROR_NONE;
548	#ifdef DMA_SUPPORT_DYN_CHANNEL_ALLOC
549	        hdma->KeepAlloc = 1;
550	#endif
551	    }
552	
553	    uart->handle.RxState = HAL_UART_STATE_READY;
554	    uart->handle.Lock = HAL_UNLOCKED;
555	    uart->handle.ErrorCode = HAL_UART_ERROR_NONE;
556	}
