558	static void sifli_uart_rx_put(struct sifli_uart *uart,
559	                              FAR const uint8_t *src, uint16_t n)
560	{
561	    FAR char *dst;
562	    sbuf_size_t size;
563	    sbuf_size_t head;
564	    sbuf_size_t tail;
565	    uint16_t i;
566	    bool added = false;
567	
568	    if (n == 0 || src == NULL)
569	    {
570	        return;
571	    }
572	
573	    dst = uart->serial.recv.buffer;
574	    size = uart->serial.recv.size;
575	    head = uart->serial.recv.head;
576	    tail = uart->serial.recv.tail;
577	
578	    for (i = 0; i < n; i++)
579	    {
580	        sbuf_size_t next = (sbuf_size_t)(head + 1);
581	
582	        if (next >= size)
583	        {
584	            next = 0;
585	        }
586	
587	        if (next == tail)
588	        {
589	            break;
590	        }
591	
592	        dst[head] = (char)src[i];
593	        head = next;
594	        added = true;
595	    }
596	
597	    uart->serial.recv.head = head;
598	    if (added)
599	    {
600	        uart_datareceived(&uart->serial);
601	    }
602	}
603	
604	static void sifli_uart_rx_drain_fifo(struct sifli_uart *uart)
605	{
606	    uint8_t buf[16];
607	    uint16_t n = 0;
608	
609	    while (n < (uint16_t)sizeof(buf) &&
610	           __HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_RXNE) != RESET)
611	    {
612	        buf[n++] = (uint8_t)__HAL_UART_GETC(&uart->handle);
613	    }
614	
615	    if (n > 0)
616	    {
617	        sifli_uart_rx_put(uart, buf, n);
618	    }
619	}
