621	static bool sifli_uart_dma_hw_alive(struct sifli_uart *uart)
622	{
623	    DMA_HandleTypeDef *hdma;
624	
625	    if (!uart->uart_rx_dma_flag || uart->dma_rx.xfer_size == 0 ||
626	        uart->handle.Instance == NULL)
627	    {
628	        return false;
629	    }
630	
631	    if ((uart->handle.Instance->CR3 & USART_CR3_DMAR) == 0)
632	    {
633	        return false;
634	    }
635	
636	    hdma = uart->handle.hdmarx;
637	    if (hdma == NULL || hdma->Instance == NULL ||
638	        hdma->State != HAL_DMA_STATE_BUSY)
639	    {
640	        return false;
641	    }
642	
643	    return (hdma->Instance->CCR & DMAC_CCR1_EN) != 0;
644	}
645	
646	static void sifli_uart_dma_harvest(struct sifli_uart *uart)
647	{
648	    irqstate_t flags;
649	    uint16_t size;
650	    uint16_t ndtr;
651	    uint16_t now;
652	    uint16_t pos;
653	    FAR const uint8_t *src;
654	
655	    flags = enter_critical_section();
656	    if (!uart->uart_rx_dma_flag || uart->dma_rx.bounce == NULL)
657	    {
658	        leave_critical_section(flags);
659	        return;
660	    }
661	
662	    size = uart->dma_rx.xfer_size;
663	    if (size == 0 || uart->handle.hdmarx == NULL ||
664	        uart->handle.hdmarx->Instance == NULL)
665	    {
666	        leave_critical_section(flags);
667	        return;
668	    }
669	
670	    ndtr = (uint16_t)__HAL_DMA_GET_COUNTER(uart->handle.hdmarx);
671	    now = (ndtr > size) ? uart->dma_rx.pos : (uint16_t)(size - ndtr);
672	    pos = uart->dma_rx.pos;
673	    src = uart->dma_rx.bounce;
674	
675	    if (now != pos)
676	    {
677	        if (now > pos)
678	        {
679	            up_invalidate_dcache((uintptr_t)(src + pos),
680	                                 (uintptr_t)(src + now));
681	            sifli_uart_rx_put(uart, src + pos, (uint16_t)(now - pos));
682	        }
683	        else
684	        {
685	            up_invalidate_dcache((uintptr_t)(src + pos),
686	                                 (uintptr_t)(src + size));
687	            sifli_uart_rx_put(uart, src + pos, (uint16_t)(size - pos));
688	            if (now > 0)
689	            {
690	                up_invalidate_dcache((uintptr_t)src,
691	                                     (uintptr_t)(src + now));
692	                sifli_uart_rx_put(uart, src, now);
693	            }
694	        }
695	
696	        uart->dma_rx.pos = now;
697	    }
698	
699	    leave_critical_section(flags);
700	}
