839	/* Reserve the UART RX channel at serialinit, before LCD/SD come up.
840	 * Same as NSH console: occupy one KeepAlloc slot and DMA IRQ for life.
841	 */
842	
843	static void sifli_uart_dma_pin(struct sifli_uart *uart)
844	{
845	    if (!uart->uart_rx_dma_flag || uart->config == NULL ||
846	        uart->config->dma_rx == NULL || uart->config->dma_rx->Instance == NULL)
847	    {
848	        return;
849	    }
850	
851	    sifli_uart_dma_bind(uart);
852	    (void)HAL_DMA_Init(uart->handle.hdmarx);
853	#ifdef DMA_SUPPORT_DYN_CHANNEL_ALLOC
854	    uart->handle.hdmarx->KeepAlloc = 1;
855	#endif
856	    sifli_uart_dma_irq_sync(uart);
857	}
858	
859	static int sifli_uart_dma_arm(struct sifli_uart *uart)
860	{
861	    HAL_StatusTypeDef st;
862	    irqstate_t flags;
863	    int tries;
864	    uint16_t size;
865	
866	    if (!uart->uart_rx_dma_flag)
867	    {
868	        return OK;
869	    }
870	
871	    if (uart->config->dma_rx == NULL || uart->config->dma_rx->Instance == NULL ||
872	        uart->dma_rx.bounce == NULL)
873	    {
874	        return -EINVAL;
875	    }
876	
877	    /* Handle.State==BUSY is not enough: PM/HAL_UART_Init can drop DMAR
878	     * while the DMA handle still looks busy, and we would never re-arm.
879	     */
880	    if (sifli_uart_dma_hw_alive(uart))
881	    {
882	        return OK;
883	    }
884	
885	    sifli_uart_dma_bind(uart);
886	
887	    size = (uint16_t)uart->serial.recv.size;
888	    if (size == 0 || size > (uint16_t)CONFIG_UART_BUFSZ)
889	    {
890	        size = (uint16_t)CONFIG_UART_BUFSZ;
891	    }
892	
893	    up_invalidate_dcache((uintptr_t)uart->dma_rx.bounce,
894	                         (uintptr_t)uart->dma_rx.bounce + size);
895	
896	    flags = enter_critical_section();
897	    sifli_uart_dma_stop(uart);
898	#ifdef DMA_SUPPORT_DYN_CHANNEL_ALLOC
899	    uart->handle.hdmarx->KeepAlloc = 1;
900	#endif
901	
902	    /* Reopen after GNSS close: callbacks already live on the pinned
903	     * handle. Restart in place; HAL_UART_Receive_DMA is first-open only.
904	     */
905	    if (uart->handle.hdmarx != NULL &&
906	        uart->handle.hdmarx->XferCpltCallback != NULL &&
907	        uart->handle.Instance != NULL)
908	    {
909	        uart->dma_rx.xfer_size = size;
910	        if (sifli_uart_dma_restart_circ(uart) == OK)
911	        {
912	            leave_critical_section(flags);
913	            return OK;
914	        }
915	    }
916	
917	    for (tries = 0; tries < 2; tries++)
918	    {
919	        sifli_uart_dma_stop(uart);
920	#ifdef DMA_SUPPORT_DYN_CHANNEL_ALLOC
921	        uart->handle.hdmarx->KeepAlloc = 1;
922	#endif
923	
924	        st = HAL_DMA_Init(uart->handle.hdmarx);
925	        if (st != HAL_OK)
926	        {
927	            uart->handle.hdmarx->State = HAL_DMA_STATE_READY;
928	            uart->handle.hdmarx->Lock = HAL_UNLOCKED;
929	#ifdef DMA_SUPPORT_DYN_CHANNEL_ALLOC
930	            uart->handle.hdmarx->KeepAlloc = 1;
931	#endif
932	            st = HAL_DMA_Init(uart->handle.hdmarx);
933	        }
934	
935	#ifdef DMA_SUPPORT_DYN_CHANNEL_ALLOC
936	        uart->handle.hdmarx->KeepAlloc = 1;
937	#endif
938	        uart->handle.RxState = HAL_UART_STATE_READY;
939	        uart->handle.Lock = HAL_UNLOCKED;
940	        uart->dma_rx.pos = 0;
941	        st = HAL_UART_Receive_DMA(&(uart->handle),
942	                                  uart->dma_rx.bounce, size);
943	        if (st == HAL_OK &&
944	            uart->handle.hdmarx->State == HAL_DMA_STATE_BUSY)
945	        {
946	            uart->dma_rx.xfer_size = size;
947	            sifli_uart_dma_irq_sync(uart);
948	            __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_IDLE);
949	            if (uart->handle.Instance != NULL)
950	            {
951	                SET_BIT(uart->handle.Instance->CR3, USART_CR3_EIE);
952	            }
953	
954	            leave_critical_section(flags);
955	            return OK;
956	        }
957	    }
958	
959	    uart->dma_rx.xfer_size = 0;
960	    leave_critical_section(flags);
961	    if (!up_interrupt_context())
962	    {
963	        syslog(LOG_ERR,
964	               "uart: RX DMA start failed st=%d dma_st=%d rx_st=%d inst=%p\n",
965	               (int)st,
966	               (int)uart->handle.hdmarx->State,
967	               (int)uart->handle.RxState,
968	               uart->handle.hdmarx->Instance);
969	    }
970	
971	    return -EIO;
972	}
