1189	static void sifli_serial_pm_setsuspend(bool suspend)
1190	{
1191	  int n;
1192	  int obj_num = sizeof(uart_obj) / sizeof(uart_obj[0]);
1193	
1194	  /* Already in desired state? */
1195	
1196	  if (suspend == g_serialpm.serial_suspended)
1197	    return;
1198	
1199	  g_serialpm.serial_suspended = suspend;
1200	
1201	
1202	  if (!suspend)
1203	  {
1204	    for (n = 0; n < obj_num; n++)
1205	    {
1206	        /* Open ports keep their DMA; HAL_UART_Init here would drop DMAR
1207	         * while the handle still looks BUSY, and GNSS goes silent.
1208	         */
1209	        if (uart_obj[n].serial.open_count != 0 ||
1210	            uart_obj[n].serial.isconsole)
1211	        {
1212	            continue;
1213	        }
1214	
1215	        sifli_setup(&uart_obj[n].serial);
1216	        sifli_attach(&uart_obj[n].serial);
1217	    }
1218	  }
1219	}
