1259	
1260	/**
1261	 * Uart common interrupt process. This need add to uart ISR.
1262	 *
1263	 * @param serial serial device
1264	 */
1265	int uart_isr(int irq, FAR void *context, FAR void *arg)
1266	{
1267	    struct sifli_uart *uart;
1268	
1269	
1270	    uart = (struct sifli_uart *) arg;
1271	
1272	    /* Clear error flags first to prevent data loss */
1273	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_ORE) != RESET)
1274	    {
1275	        __HAL_UART_CLEAR_OREFLAG(&uart->handle);
1276	        if (uart->uart_rx_dma_flag)
1277	        {
1278	            /* FIFO overflowed. If circular DMA is still running, just
1279	             * harvest; aborting frees the dyn channel and races SPI/SD.
1280	             */
1281	            if (sifli_uart_dma_hw_alive(uart))
1282	            {
1283	                sifli_uart_dma_harvest(uart);
1284	                sifli_uart_rx_drain_fifo(uart);
1285	            }
1286	            else
1287	            {
1288	                sifli_uart_dma_recover(uart);
1289	            }
1290	        }
1291	    }
1292	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_NE) != RESET)
1293	    {
1294	        __HAL_UART_CLEAR_NEFLAG(&uart->handle);
1295	    }
1296	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_FE) != RESET)
1297	    {
1298	        __HAL_UART_CLEAR_FEFLAG(&uart->handle);
1299	    }
1300	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_PE) != RESET)
1301	    {
1302	        __HAL_UART_CLEAR_PEFLAG(&uart->handle);
1303	    }
1304	
1305	    /* UART in mode Receiver -------------------------------------------------*/
1306	    if (!uart->uart_rx_dma_flag &&
1307	        __HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_RXNE) != RESET)
1308	    {
1309	        uart_recvchars(&(uart->serial));
1310	    }
1311	
1312	    /* DMA RX: copy new bounce bytes; leave circular DMA running. */
1313	    if ((uart->uart_rx_dma_flag) && (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_IDLE) != RESET))
1314	    {
1315	        __HAL_UART_CLEAR_IDLEFLAG(&uart->handle);
1316	        sifli_uart_dma_poll(uart);
1317	    }
1318	    else if (uart->uart_rx_dma_flag && uart->dma_rx.need_recover)
1319	    {
1320	        sifli_uart_dma_recover(uart);
1321	    }
1322	
1323	    if (!uart->uart_tx_dma_flag &&
1324	        __HAL_UART_GET_IT_SOURCE(&(uart->handle), UART_IT_TXE) &&
1325	        __HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_TXE) != RESET)
1326	    {
1327	        uart_xmitchars(&uart->serial);
1328	    }
1329	
1330	    /* DMA TX complete interrupt */
1331	    if ((uart->uart_tx_dma_flag) && (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_TC) != RESET))
1332	    {
1333	        __HAL_UART_CLEAR_FLAG(&uart->handle, UART_CLEAR_TCF);
1334	        uart->handle.gState = HAL_UART_STATE_READY;
1335	        uart_xmitchars(&uart->serial);
1336	    }
1337	
1338	    /* Clear remaining flags */
1339	    if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_CTS) != RESET)
1340	    {
1341	        UART_INSTANCE_CLEAR_FUNCTION(&(uart->handle), UART_FLAG_CTS);
1342	    }
1343	
1344	    return OK;
1345	}
