1481	void arm_serialinit(void)
1482	{
1483	    unsigned minor = 0;
1484	    unsigned i     = 0;
1485	    char devname[16];
1486	    int obj_num = sizeof(uart_obj) / sizeof(struct sifli_uart);
1487	    struct serial_configure config = RT_SERIAL_CONFIG_DEFAULT;
1488	
1489	#ifdef CONFIG_PM
1490	  int ret;
1491	#endif
1492	
1493	#ifdef CONFIG_PM
1494	    ret = pm_register(&g_serialpm.pm_cb);
1495	    DEBUGASSERT(ret == OK);
1496	    UNUSED(ret);
1497	#endif
1498	
1499	    sifli_usart_init();
1500	
1501	    for (i = 0; i < obj_num; i++)
1502	    {
1503	        uart_obj[i].config = &(uart_config[i]);
1504	        uart_obj[i].serial.ops = &g_uart_ops;
1505	        uart_obj[i].serial.priv = &uart_obj[i];
1506	        uart_obj[i].serial.xmit.size = CONFIG_UART_BUFSZ;
1507	        uart_obj[i].serial.xmit.buffer = g_uart_buffer[2*i];
1508	        uart_obj[i].serial.recv.size = CONFIG_UART_BUFSZ;
1509	        uart_obj[i].serial.recv.buffer = g_uart_buffer[2*i+1];
1510	        uart_obj[i].dma_rx.bounce = g_uart_dma_rx[i];
1511	        uart_obj[i].dma_rx.xfer_size = 0;
1512	        uart_obj[i].dma_rx.pos = 0;
1513	        uart_obj[i].dma_rx.need_recover = 0;
1514	        uart_obj[i].dma_rx.recovering = 0;
1515	        uart_obj[i].ser_cfg=config;
1516	        uart_obj[i].dma_nvic_irq = -1;
1517	        sifli_uart_dma_pin(&uart_obj[i]);
1518	#ifdef CONSOLE_UART
1519	        if (i == (CONSOLE_UART -1))
1520	        {
1521	            // uart_obj[i].serial.isconsole = true;
1522	        }
1523	#endif /* CONSOLE_UART */        
1524	    }
1525	    
1526	#ifdef CONSOLE_UART
1527	    /* Register the serial console */
1528	    /* isconsole was already set in arm_earlyserialinit */
1529	    
1530	    uart_register("/dev/console", &(uart_obj[CONSOLE_UART-1].serial));
1531	#endif
1532	
1533	    /* Register all remaining UARTs */
1534	    strcpy(devname, "/dev/ttySx");
1535	    for (i = 1; i <= obj_num; i++)
1536	    {
1537	        /* Register USARTs as devices in increasing order */
1538	#ifdef CONSOLE_UART
1539	        if (i==CONSOLE_UART)
1540	            continue;
1541	#endif        
1542	        
1543	        devname[9] = '0' + minor++;
1544	        uart_register(devname, &(uart_obj[i-1].serial));
1545	    }
1546	}
