104	/** @brief HCPU 通用外设 pinmux（SDIO/UART/I2C/按键/ETA9184/USB 等）。 */
105	static void BSP_PIN_Common(void)
106	{
107	#ifdef SOC_BF0_HCPU
108	    // HCPU pins
109	
110	    uint32_t pid = (hwp_hpsys_cfg->IDR & HPSYS_CFG_IDR_PID_Msk) >> HPSYS_CFG_IDR_PID_Pos;
111	
112	    pid &= 7;
113	
114	#ifdef BSP_USING_PSRAM1
115	#if defined(CONFIG_BSP_USING_SPI_NAND)
116	    /* NAND boot: the application is executing XIP from PSRAM via MPI1 right
117	     * now, and the secondary bootloader already configured the MPI1/PSRAM
118	     * pads. Re-running HAL_PIN_Set() on these live pads glitches the
119	     * instruction-fetch path and intermittently crashes the CPU (it only
120	     * survives when the next instructions happen to already be in I-cache,
121	     * which is why the hang was random). Leave the pads exactly as the
122	     * bootloader set them. */
123	    (void)pid;
124	#else
125	    switch (pid)
126	    {
127	    case 5: //BOOT_PSRAM_APS_16P:
128	        board_pinmux_psram_func3();         // 16Mb APM QSPI PSRAM
129	        break;
130	    case 4: //BOOT_PSRAM_APS_32P:
131	        board_pinmux_psram_func1_2_4(2);    // 32Mb APM LEGACY PSRAM
132	        break;
133	    case 6: //BOOT_PSRAM_WINBOND:                // Winbond HYPERBUS PSRAM
134	        board_pinmux_psram_func1_2_4(4);
135	        break;
136	    case 3: // BOOT_PSRAM_APS_64P:
137	        board_pinmux_psram_func1_2_4(1);    // 64Mb APM XCELLA PSRAM
138	        break;
139	    case 2: //BOOT_PSRAM_APS_128P:
140	        board_pinmux_psram_func0();         // 128Mb APM XCELLA PSRAM
141	        break;
142	    default:
143	        board_pinmux_mpi1_none();
144	        break;
145	    }
146	#endif /* CONFIG_BSP_USING_SPI_NAND */
147	#endif /* BSP_USING_PSRAM1 */
148	#ifndef BSP_USING_BOARD_SF32LB52_LCD_52J_SD
149	#if defined(BSP_USING_SDIO) && defined(BSP_ENABLE_MPI2)
