73	/** @brief 按芯片 PID 选择 PSRAM 模式并 HAL_MPI_PSRAM_Init。 */
74	static void board_init_psram(void)
75	{
76	    qspi_configure_t qspi_cfg =
77	    {
78	        .Instance = hwp_qspi1,
79	        .SpiMode = BSP_QSPI1_MODE,
80	        .msize = BSP_QSPI1_MEM_SIZE,
81	        .base = QSPI1_MEM_BASE,
82	    };
83	    uint32_t pid = (hwp_hpsys_cfg->IDR & HPSYS_CFG_IDR_PID_Msk) >> HPSYS_CFG_IDR_PID_Pos;
84	    pid &= 7;
85	
86	    switch (pid)
87	    {
88	    case 5: //BOOT_PSRAM_APS_16P:
89	        qspi_cfg.SpiMode = SPI_MODE_PSRAM;         // 16Mb APM QSPI PSRAM
90	        break;
91	    case 4: //BOOT_PSRAM_APS_32P:
92	        qspi_cfg.SpiMode = SPI_MODE_LEGPSRAM;    // 32Mb APM LEGACY PSRAM
93	        break;
94	    case 6: //BOOT_PSRAM_WINBOND:                // Winbond HYPERBUS PSRAM
95	        qspi_cfg.SpiMode = SPI_MODE_HBPSRAM;
96	        break;
97	    case 3: // BOOT_PSRAM_APS_64P:
98	    case 2: //BOOT_PSRAM_APS_128P:
99	        qspi_cfg.SpiMode = SPI_MODE_OPSRAM;      // 64Mb APM XCELLA PSRAM
100	        break;
101	    default:
102	        qspi_cfg.SpiMode = SPI_MODE_NOR;
103	        break;
104	    }
105	    static FLASH_HandleTypeDef f_handle;
106	    if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
107	        f_handle.wakeup = 0;
108	    else
109	        f_handle.wakeup = 1;
110	    HAL_MPI_PSRAM_Init(&f_handle, &qspi_cfg, mpi1_div);
111	}
112	#endif
