174	/**
175	 * @brief 使能 DLL2 + MPI 分频 + FLASH1/2 路由（PSRAM 144MHz，NAND 72MHz）。
176	 *
177	 * 不提升 HCLK 至 240MHz；PSRAM XIP 启动时在 pinmux 之后调用更安全。
178	 */
179	void BSP_Board_EnableSdkFlashClocks(void)
180	{
181	#ifdef SOC_BF0_HCPU
182	#if defined(CONFIG_BSP_USING_SPI_NAND)
183	  /* Bootloader already configured MPI1/PSRAM (FLASH1<-DLL2, div=2, ~144MHz)
184	   * for XIP. Do not touch FLASH1/DLL2 here. NAND FLASH2 clocks are raised in
185	   * BSP_Board_EnableNandMpiClocks() before HAL_FLASH_Init. */
186	  mpi1_div = 2;
187	  mpi2_div = 4;
188	  return;
189	#endif
190	
191	#if defined(BSP_USING_USBD) || defined(BSP_USING_USBH)
192	    HAL_RCC_HCPU_EnableDLL2(240000000);
193	    hwp_hpsys_rcc->USBCR = 4;
194	    hwp_hpsys_rcc->CSR |= HPSYS_RCC_CSR_SEL_USBC;
195	#else
196	    HAL_RCC_HCPU_EnableDLL2(288000000);
197	#endif
198	
199	    HAL_Delay_us(0);
200	
201	    mpi1_div = 2;
202	    mpi2_div = 4;
203	
204	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_DLL2);
205	#if defined(BSP_USING_PSRAM)
206	    HAL_PMU_ConfigPeriLdo(PMU_PERI_LDO_1V8, true, true);
207	#if !defined(CONFIG_BSP_USING_SPI_NAND)
208	    board_init_psram();
209	#endif
210	#endif
211	
212	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH2, RCC_CLK_FLASH_DLL2);
213	#if defined(BSP_USING_NOR_FLASH1) || defined(BSP_USING_NOR_FLASH2)
214	    // TODO: move select FLASH1 clock to here if MPI1 used as FLASH.
215	#ifdef BSP_USING_NOR_FLASH1
216	    mpi1_div = 3;
217	#endif
218	    if (PM_STANDBY_BOOT == SystemPowerOnModeGet())
219	    {
220	        //TODO: pin device is not restored
221	        HAL_HPAON_ENABLE_PAD();
222	        /* rt_hw_flash_init cannot be called as data has not been restored at this moment,
223	           so rt_sem_init cannot be called */
224	#if defined(BSP_USING_NOR_FLASH1)
225	        BSP_Flash_hw1_init();
226	#endif
227	#if defined(BSP_USING_NOR_FLASH2)
228	        BSP_Flash_hw2_init();
229	#endif
230	    }
231	    else
232	    {
233	#ifdef BSP_USING_RTTHREAD
234	        rt_hw_flash_init();
235	#else
236	        BSP_Flash_Init();
237	#endif
238	    }
239	#endif /* BSP_USING_NOR_FLASH1 || BSP_USING_NOR_FLASH2 */
240	#endif /* SOC_BF0_HCPU */
241	}
