264	/**
265	 * @brief 根据 RCC 源与 BSP 分频计算 MPI 时钟频率。
266	 * @param clk_module RCC 时钟模块（FLASH1/FLASH2）。
267	 * @param clk_div 软件分频系数。
268	 * @param hcpu 非 0 为 HCPU，0 为 LCPU。
269	 * @return Hz；clk_div&lt;=0 返回 0。
270	 */
271	uint32_t flash_get_freq(int clk_module, uint16_t clk_div, uint8_t hcpu)
272	{
273	  int src;
274	  uint32_t freq;
275	
276	  if (clk_div <= 0)
277	    {
278	      return 0;
279	    }
280	
281	  if (hcpu == 0)
282	    {
283	      freq = HAL_RCC_GetSysCLKFreq(CORE_ID_LCPU);
284	      return freq / clk_div;
285	    }
286	
287	  src = HAL_RCC_HCPU_GetClockSrc(clk_module);
288	#ifdef SOC_SF32LB52X
289	  if (RCC_CLK_FLASH_DLL2 == src)
290	    {
291	      freq = HAL_RCC_HCPU_GetDLL2Freq();
292	    }
293	  else if (RCC_CLK_SRC_DLL1 == src)
294	    {
295	      freq = HAL_RCC_HCPU_GetDLL1Freq();
296	    }
297	  else if (3 == src)
298	    {
299	      freq = 96000000;
300	    }
301	  else
302	    {
303	      freq = HAL_RCC_GetSysCLKFreq(CORE_ID_HCPU);
304	    }
305	#else
306	  if (RCC_CLK_FLASH_DLL2 == src)
307	    {
308	      freq = HAL_RCC_HCPU_GetDLL2Freq();
309	    }
310	  else
311	    {
312	      freq = HAL_RCC_GetSysCLKFreq(CORE_ID_HCPU);
313	    }
314	#endif
315	
316	  return freq / clk_div;
317	}
