364	/** @brief 打印 HCPU sysclk/hclk 与 FLASH1/2 MPI 频率（NAND XIP 诊断）。 */
365	void BSP_Board_PrintClocks(void)
366	{
367	  uint32_t sysclk;
368	  uint32_t hclk;
369	  int sys_src;
370	  int flash1_src;
371	  int flash2_src;
372	  uint32_t flash1_hz;
373	  uint32_t flash2_hz;
374	  uint32_t dll2_hz;
375	  uint8_t mpi1_psclr;
376	  uint8_t mpi2_psclr;
377	  bool dll2_en;
378	
379	  sysclk = HAL_RCC_GetSysCLKFreq(CORE_ID_HCPU);
380	  hclk = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
381	  sys_src = HAL_RCC_HCPU_GetClockSrc(RCC_CLK_MOD_SYS);
382	  flash1_src = HAL_RCC_HCPU_GetClockSrc(RCC_CLK_MOD_FLASH1);
383	  flash2_src = HAL_RCC_HCPU_GetClockSrc(RCC_CLK_MOD_FLASH2);
384	
385	  flash1_hz = flash_get_freq(RCC_CLK_MOD_FLASH1, BSP_GetFlash1DIV(), 1);
386	  flash2_hz = flash_get_freq(RCC_CLK_MOD_FLASH2, BSP_GetFlash2DIV(), 1);
387	
388	  mpi1_psclr = bsp_mpi_hw_psclr_div(hwp_qspi1);
389	  mpi2_psclr = bsp_mpi_hw_psclr_div(hwp_qspi2);
390	
391	  dll2_en = (hwp_hpsys_rcc->DLL2CR & HPSYS_RCC_DLL2CR_EN) != 0;
392	  dll2_hz = dll2_en ? HAL_RCC_HCPU_GetDLL2Freq() : 0;
393	
394	  syslog(LOG_INFO, "CLK: HCPU sysclk=%lu Hz (%s) hclk=%lu Hz\n",
395	         (unsigned long)sysclk, bsp_clk_sys_src_name(sys_src),
396	         (unsigned long)hclk);
397	  syslog(LOG_INFO,
398	         "CLK: DLL2 %s (%lu Hz) FLASH1=%s sw_div=%u hw_psclr=%u ~%lu Hz (PSRAM XIP)\n",
399	         dll2_en ? "on" : "off", (unsigned long)dll2_hz,
400	         bsp_clk_flash_src_name(flash1_src),
401	         (unsigned)BSP_GetFlash1DIV(), (unsigned)mpi1_psclr,
402	         (unsigned long)flash1_hz);
403	  syslog(LOG_INFO,
404	         "CLK: FLASH2=%s sw_div=%u hw_psclr=%u ~%lu Hz (NAND)\n",
405	         bsp_clk_flash_src_name(flash2_src),
406	         (unsigned)BSP_GetFlash2DIV(), (unsigned)mpi2_psclr,
407	         (unsigned long)flash2_hz);
408	}
