196	/** @brief 创建目录，EEXIST 视为成功。 */
197	static int bringup_mkdir(const char *path)
198	{
199	  clock_t t0;
200	  uint32_t ms;
201	  int ret;
202	  int err = 0;
203	
204	  syslog(LOG_INFO, "INFO: mkdir %s ...\n", path);
205	  t0 = clock_systime_ticks();
206	  myvendor_watchdog_busy_pump();
207	  ret = mkdir(path, 0755);
208	  if (ret < 0)
209	    {
210	      err = errno;
211	    }
212	
213	  ms = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);
214	  syslog(LOG_INFO, "INFO: mkdir %s ret=%d errno=%d %ums\n",
215	         path, ret, err, (unsigned)ms);
216	
217	  if (ret < 0 && err != EEXIST)
218	    {
219	      serr("WARN: mkdir %s failed: %d\n", path, err);
220	      return -err;
221	    }
222	
223	  return OK;
224	}
