388	/** @brief 等 companion 退出；仍活着则禁止复用 g_ble_companion_stack。 */
389	static int ble_companion_wait_gone(pid_t pid, unsigned wait_ms)
390	{
391	  unsigned steps;
392	  unsigned i;
393	
394	  if (pid <= 0)
395	    {
396	      return 0;
397	    }
398	
399	  steps = (wait_ms + 99u) / 100u;
400	  for (i = 0; i < steps; i++)
401	    {
402	      if (!ble_companion_pid_alive(pid))
403	        {
404	          return 0;
405	        }
406	
407	      usleep(100 * 1000);
408	    }
409	
410	  return ble_companion_pid_alive(pid) ? -ETIMEDOUT : 0;
411	}
