413	/** @brief 异步 task_spawn 启动 ble_companion。 */
414	void board_start_ble_companion_async(void)
415	{
416	  posix_spawnattr_t attr;
417	  FAR char *argv[] = { NULL };
418	  int pid;
419	
420	  if (g_ble_companion_spawning ||
421	      ble_companion_pid_alive(g_ble_companion_pid))
422	    {
423	      syslog(LOG_ERR, "ble_companion: spawn refused pid=%d\n",
424	             (int)g_ble_companion_pid);
425	      return;
426	    }
427	
428	  g_ble_companion_spawning = true;
429	  posix_spawnattr_init(&attr);
430	  attr.priority  = CONFIG_MYVENDOR_BLE_COMPANION_PRIORITY;
431	  attr.stacksize = sizeof(g_ble_companion_stack);
432	  posix_spawnattr_setstackaddr(&attr, g_ble_companion_stack);
433	
434	  pid = task_spawn("ble_companion", ble_companion_main, NULL, &attr,
435	                   argv, NULL);
436	  if (pid < 0)
437	    {
438	      g_ble_companion_pid = (pid_t)-1;
439	      syslog(LOG_ERR, "ERROR: task_spawn ble_companion failed: %d\n", pid);
440	    }
441	  else
442	    {
443	      g_ble_companion_pid = (pid_t)pid;
444	      syslog(LOG_INFO, "INFO: ble_companion async started pid=%d\n", pid);
445	    }
446	
447	  g_ble_companion_spawning = false;
448	}
