459	/**
460	 * @brief 界面起来后再开 BLE：取消开机兜底，过一小会再 spawn。
461	 *
462	 * LCPU RF 校准会占 CPU，不能和开机音、首帧刷屏叠在一起。
463	 */
464	void board_ble_companion_start_after_ui(void)
465	{
466	#ifdef CONFIG_SCHED_LPWORK
467	  int ret;
468	
469	  if (g_ble_start_requested ||
470	      g_ble_companion_spawning ||
471	      ble_companion_pid_alive(g_ble_companion_pid))
472	    {
473	      return;
474	    }
475	
476	  g_ble_start_requested = true;
477	  (void)work_cancel(LPWORK, &g_ble_deferred_work);
478	  ret = work_queue(LPWORK, &g_ble_deferred_work, ble_companion_deferred_worker,
479	                   NULL, MSEC2TICK(1500));
480	  if (ret < 0)
481	    {
482	      syslog(LOG_WARNING,
483	             "WARN: ble_companion defer queue failed %d, spawn now\n", ret);
484	      board_start_ble_companion_async();
485	    }
486	  else
487	    {
488	      syslog(LOG_INFO, "INFO: ble_companion in 1.5s after UI\n");
489	    }
490	#else
491	  g_ble_start_requested = true;
492	  board_start_ble_companion_async();
493	#endif
494	}
