496	int board_restart_ble_companion(void)
497	{
498	  pid_t pid;
499	
500	  if (g_ble_companion_spawning || g_ble_companion_restarting)
501	    {
502	      syslog(LOG_WARNING, "ble_companion: restart busy\n");
503	      return -EBUSY;
504	    }
505	
506	  g_ble_companion_restarting = true;
507	  pid = g_ble_companion_pid;
508	  BLE_LOG("restart begin pid=%d spawn=%d",
509	          (int)pid, g_ble_companion_spawning ? 1 : 0);
510	
511	  if (ble_companion_pid_alive(pid))
512	    {
513	      syslog(LOG_ERR, "ble_companion: stall dump pid=%d phase=%s\n",
514	             (int)pid,
515	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
516	             companion_bridge_phase_get()
517	#else
518	             "-"
519	#endif
520	             );
521	#ifdef CONFIG_BLUETOOTH
522	      sf32lb52_bt_hci_dump_stall();
523	#endif
524	#ifdef CONFIG_SCHED_BACKTRACE
525	      sched_dumpstack(pid);
526	#endif
527	    }
528	
529	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
530	  companion_bridge_teardown_skip_hci_set(true);
531	#endif
532	#ifdef CONFIG_BLUETOOTH
533	  /* 先让 HCI 轮询到 skip：LCPU 复位成功也不要清 skip，
534	   * 否则 companion 仍堵在不可中断等待里会再发同步命令。 */
535	  sf32lb52_bt_hci_skip_sync_set(true);
536	#endif
537	
538	  if (ble_companion_pid_alive(pid))
539	    {
540	      syslog(LOG_WARNING, "ble_companion: SIGTERM pid=%d\n", (int)pid);
541	      (void)kill(pid, SIGTERM);
542	      if (ble_companion_wait_gone(pid, 1500u) != 0)
543	        {
544	          syslog(LOG_ERR, "ble_companion: SIGKILL pid=%d\n", (int)pid);
545	          (void)kill(pid, SIGKILL);
546	          (void)ble_companion_wait_gone(pid, 500u);
547	        }
548	
549	      if (ble_companion_pid_alive(pid))
550	        {
551	          syslog(LOG_ERR, "ble_companion: task_delete pid=%d\n", (int)pid);
552	          (void)task_delete(pid);
553	          (void)ble_companion_wait_gone(pid, 1000u);
554	        }
555	    }
556	
557	  if (ble_companion_pid_alive(pid) ||
558	      ble_companion_pid_alive(g_ble_companion_pid))
559	    {
560	      syslog(LOG_ERR, "ble_companion: still alive pid=%d, skip respawn\n",
561	             (int)(g_ble_companion_pid > 0 ? g_ble_companion_pid : pid));
562	      BLE_LOG("restart abort still-alive keep skip_sync");
563	      g_ble_companion_restarting = false;
564	      return -EBUSY;
565	    }
566	
567	  g_ble_companion_pid = (pid_t)-1;
568	  ble_companion_reap_if_dead();
569	#ifdef CONFIG_BLUETOOTH
570	  BLE_LOG("restart lcpu reset then clear skip and spawn");
571	  (void)sf32lb52_bt_controller_force_reset();
572	  sf32lb52_bt_hci_skip_sync_set(false);
573	#endif
574	#ifdef CONFIG_MYVENDOR_BLE_COMPANION
575	  companion_bridge_teardown_skip_hci_set(false);
576	#endif
577	  usleep(100 * 1000);
578	  board_start_ble_companion_async();
579	  g_ble_companion_restarting = false;
580	  BLE_LOG("restart spawn pid=%d", (int)g_ble_companion_pid);
581	  return g_ble_companion_pid > 0 ? 0 : -EIO;
582	}
583	#endif
