615	#define LCD_BRINGUP_STACK_ALIGN 16u
616	
617	/* One-shot boot task: retain its small BoardPSRAM stack after exit rather
618	 * than reserving 8 KiB of scarce HCPU SRAM forever. */
619	static void *g_lcd_bringup_stack_raw;
620	static void *g_lcd_bringup_stack;
621	
622	static void *lcd_bringup_stack_alloc(void)
623	{
624	  uintptr_t aligned;
625	
626	  if (g_lcd_bringup_stack != NULL)
627	    {
628	      return g_lcd_bringup_stack;
629	    }
630	
631	  g_lcd_bringup_stack_raw = board_malloc_psram(
632	      LCD_BRINGUP_STACKSIZE + LCD_BRINGUP_STACK_ALIGN - 1u);
633	  if (g_lcd_bringup_stack_raw == NULL ||
634	      !board_ptr_in_psram_pool(g_lcd_bringup_stack_raw))
635	    {
636	      board_mem_free(g_lcd_bringup_stack_raw);
637	      g_lcd_bringup_stack_raw = NULL;
638	      return NULL;
639	    }
640	
641	  aligned = ((uintptr_t)g_lcd_bringup_stack_raw +
642	             LCD_BRINGUP_STACK_ALIGN - 1u) &
643	            ~((uintptr_t)LCD_BRINGUP_STACK_ALIGN - 1u);
644	  g_lcd_bringup_stack = (void *)aligned;
645	  return g_lcd_bringup_stack;
646	}
