730	/** @brief 注册 RTC 并设置/读取启动时间。 */
731	static int bringup_rtc(void)
732	{
733	#if defined(CONFIG_RTC) && defined(CONFIG_RTC_DRIVER)
734	  struct rtc_lowerhalf_s *rtclower;
735	  int ret;
736	  int rtcfd;
737	
738	  rtclower = sf32lb_rtc_lowerhalf();
739	  if (rtclower == NULL)
740	    {
741	      serr("ERROR: Failed to instantiate RTC lower-half\n");
742	      return -ENOMEM;
743	    }
744	
745	  ret = rtc_initialize(0, rtclower);
746	  if (ret < 0)
747	    {
748	      serr("ERROR: rtc_initialize failed: %d\n", ret);
749	      return ret;
750	    }
751	
752	  rtcfd = open("/dev/rtc0", O_RDWR);
753	  if (rtcfd < 0)
754	    {
755	      rtcfd = open("/dev/rtc0", O_RDONLY);
756	    }
757	
758	  if (rtcfd < 0)
759	    {
760	      serr("ERROR: open /dev/rtc0 failed: %d\n", errno);
761	    }
762	  else
763	    {
764	      struct rtc_time rt;
765	      bool trusted = sf32lb_rtc_trust_is_valid();
766	
767	      memset(&rt, 0, sizeof(rt));
768	      if (!trusted)
769	        {
770	          rt.tm_year = 100;
771	          rt.tm_mon  = 0;
772	          rt.tm_mday = 1;
773	          if (ioctl(rtcfd, RTC_SET_TIME,
774	                    (unsigned long)(uintptr_t)&rt) < 0)
775	            {
776	              serr("ERROR: RTC_SET_TIME baseline failed: %d\n", errno);
777	            }
778	          else
779	            {
780	              trusted = true;
781	            }
782	        }
783	
784	      memset(&rt, 0, sizeof(rt));
785	      if (ioctl(rtcfd, RTC_RD_TIME, (unsigned long)(uintptr_t)&rt) < 0)
786	        {
787	          serr("ERROR: RTC_RD_TIME failed: %d\n", errno);
788	        }
789	      else
790	        {
791	          syslog(LOG_WARNING,
792	                 "[rtc] boot %04d-%02d-%02d %02d:%02d:%02d trusted=%d "
793	                 "(magic=0x%08x; use 'test rtc' to change)\n",
794	                 rt.tm_year + 1900, rt.tm_mon + 1, rt.tm_mday,
795	                 rt.tm_hour, rt.tm_min, rt.tm_sec,
796	                 trusted ? 1 : 0, SF32LB_RTC_TRUST_MAGIC);
797	        }
798	
799	      close(rtcfd);
800	    }
801	#endif
802	
803	  return OK;
804	}
