1240	    /* Probe IMU first. Missing baro/mag can NACK or hang 5s and must not
1241	     * delay or tear down BMI270. */
1242	    for (attempt = 0; attempt < 3; attempt++)
1243	      {
1244	        ret = sf32lb52_bmi270_register(0, i2c0, CONFIG_BOARD_BMI270_I2C_ADDR);
1245	        if (ret == 0)
1246	          {
1247	            break;
1248	          }
1249	
1250	        syslog(LOG_ERR,
1251	               "ERROR: sf32lb52_bmi270_register failed: %d (try %d/3)\n",
1252	               ret, attempt + 1);
1253	        usleep(200000);
1254	      }
1255	  }
1256	#endif
1257	
1258	#ifdef CONFIG_BOARD_BMP388
1259	  ret = bmp388_register(0, i2c0);
1260	  if (ret < 0)
1261	    {
1262	      syslog(LOG_WARNING,
1263	             "WARN: bmp388 absent (register %d), IMU still used\n", ret);
1264	    }
1265	#endif
1266	
1267	#ifdef CONFIG_BOARD_MMC5983MA
1268	  ret = mmc5983ma_register(0, i2c0);
1269	  if (ret < 0)
1270	    {
1271	      syslog(LOG_WARNING,
1272	             "WARN: mmc5983 absent (register %d), IMU still used\n", ret);
1273	    }
1274	#endif
1275	
1276	  BRINGUP_LOG("I2C sensor bringup complete\n");
1277	#endif
1278	
1279	  return OK;
1280	}
