1481	  { "watchdog",  bringup_watchdog,  false },
1482	  { "vfs",       bringup_vfs,       false },
1483	  { "rtc",       bringup_rtc,       true  },
1484	  { "adc",       bringup_adc,       true  },
1485	  { "gpio",      bringup_gpio,      true  },
1486	  { "pwm",       bringup_pwm,       true  },
1487	  { "lcd",       bringup_lcd,       false },
1488	  { "cpuload",   bringup_cpuload,   false },
1489	  { "timer",     bringup_timer,     true  },
1490	  { "buttons",   bringup_buttons,   true  },
1491	  { "sound",     bringup_sound,     false },
1492	  { "eta9184",   bringup_eta9184,   false },
1493	  { "storage",   bringup_storage,   false },
1494	  { "devctl",    bringup_devctl,    false },
1495	  { "hclk240",   bringup_hclk240,   false },
1496	  { "clocks",    bringup_clocks,    false },
1497	  { "bicycle",   bringup_bicycle,   false },
1498	  { "gnss_prep", bringup_gnss_prep, false },
1499	  { "gnss",      bringup_gnss,      false },
1500	  { "i2c",       bringup_i2c,       true  },
1501	  { "sensors",   bringup_board_sensor, false },
1502	  { "spi",       bringup_spi,       false },
1503	  { "identity",  bringup_identity,  false },
1504	  { "usbmtp",    bringup_usbmtp,    false },
1505	  { "mtp",       bringup_mtp,       false },
1506	  { "bth4",      bringup_bth4,      false },
1507	  { "ble",       bringup_ble,       false },
1508	  { "diag",      bringup_diag,      false },
1509	};
