1511	/**
1512	 * @brief 按 g_bringup[] 顺序执行板级晚初始化。
1513	 * @return 0 全部完成或仅非 abort 步骤失败；负值为 abort_on_fail 步骤失败码。
1514	 */
1515	int sf32lb52_devkit_lcd_bringup(void)
1516	{
1517	  const size_t n = sizeof(g_bringup) / sizeof(g_bringup[0]);
1518	  size_t i;
1519	  int ret;
1520	
1521	  BRINGUP_LOG("enter, %u steps\n", (unsigned)n);
1522	
1523	  for (i = 0; i < n; i++)
1524	    {
1525	      BRINGUP_LOG("[%u/%u] %s\n",
1526	                  (unsigned)(i + 1), (unsigned)n, g_bringup[i].name);
1527	      myvendor_watchdog_busy_pump();
1528	      ret = g_bringup[i].fn();
1529	      if (ret < 0)
1530	        {
1531	          if (g_bringup[i].abort_on_fail)
1532	            {
1533	              syslog(LOG_ERR, "BRINGUP: %s abort %d\n",
1534	                     g_bringup[i].name, ret);
1535	#ifdef CONFIG_MYVENDOR_WATCHDOG
1536	              myvendor_watchdog_start();
1537	#endif
1538	              return ret;
1539	            }
1540	
1541	          syslog(LOG_WARNING, "BRINGUP: %s fail %d, continue\n",
1542	                 g_bringup[i].name, ret);
1543	        }
1544	    }
1545	
1546	#ifdef CONFIG_MYVENDOR_WATCHDOG
1547	  myvendor_watchdog_start();
1548	#endif
1549	
1550	  BRINGUP_LOG("done\n");
1551	  return OK;
1552	}
