1	/**
2	 * @file test_iowrite.c
3	 * @brief test iowrite：PWR_MD（PA27）与 GNSS_PWR（PA43，MAX-M10S-00B-01 VCC）。
4	 *
5	 * SPDX-License-Identifier: Apache-2.0
6	 */
7	
8	#include <nuttx/config.h>
9	
10	#include <stdbool.h>
11	#include <stdio.h>
12	#include <stdlib.h>
13	#include <string.h>
14	#include <unistd.h>
15	
16	#ifdef UNUSED
17	#  undef UNUSED
18	#endif
19	#include "bf0_hal.h"
20	#include "drv_io.h"
21	
22	#define IOWRITE_TOGGLE_US  2000000u
23	#define IOWRITE_COLS       4
24	#define IOWRITE_COLW       16
25	
26	#define IOWRITE_PIN_PWR    0
27	#define IOWRITE_PIN_GNSS   1
28	
29	struct iowrite_pin_s
30	{
31	  FAR const char *name;
32	  int pad;
33	  pin_function gpio_func;
34	  int gpio_pin;
35	};
36	
37	static const struct iowrite_pin_s g_iowrite_pins[] =
38	{
39	  { "PWR_MD",   PAD_PA27, GPIO_A27, 27 },
40	  { "GNSS_PWR", PAD_PA43, GPIO_A43, 43 },
41	};
42	
43	#define IOWRITE_COUNT  (sizeof(g_iowrite_pins) / sizeof(g_iowrite_pins[0]))
44	
45	/** @brief 打印用法。 */
46	static void iowrite_usage(void)
47	{
48	  printf("test iowrite: usage: test iowrite [pwr|gnss|all] [0|1|loop]\n"
49	         "  pwr  PA27 PWR_MD   HIGH=FPWM LOW=PFM (default pin)\n"
50	         "  gnss PA43 GNSS_PWR GPIO level"
51	#ifdef CONFIG_BOARD_L96_GNSS_PWR_ACTIVE_HIGH
52	         " (HIGH=module on)\n"
53	#else
54	         " (LOW=module on, active-low)\n"
55	#endif
56	         "  omitted pin name keeps old PWR_MD-only command\n");
57	}
58	
59	/** @brief 配置引脚为输出并设电平。 */
60	static void iowrite_cfg_out(FAR const struct iowrite_pin_s *p, bool high)
61	{
62	  HAL_PIN_Set(p->pad, p->gpio_func, PIN_NOPULL, 1);
63	  BSP_GPIO_Set(p->gpio_pin, high ? 1 : 0, 1);
64	}
65	
66	/** @brief 打印 mask 内引脚的输出电平。 */
67	static void iowrite_print(FAR const bool *level, unsigned mask)
68	{
69	  size_t i;
70	  size_t j;
71	  size_t n;
72	  size_t idx[IOWRITE_COUNT];
73	  size_t shown = 0;
74	
75	  for (i = 0; i < IOWRITE_COUNT; i++)
76	    {
77	      if ((mask & (1u << i)) != 0)
78	        {
79	          idx[shown++] = i;
80	        }
81	    }
82	
83	  for (i = 0; i < shown; i += IOWRITE_COLS)
84	    {
85	      n = shown - i;
86	      if (n > IOWRITE_COLS)
87	        {
88	          n = IOWRITE_COLS;
89	        }
90	
91	      for (j = 0; j < n; j++)
92	        {
93	          printf("%-*s", IOWRITE_COLW, g_iowrite_pins[idx[i + j]].name);
94	        }
95	
96	      printf("\n");
97	
98	      for (j = 0; j < n; j++)
99	        {
100	          printf("%-*s", IOWRITE_COLW, level[idx[i + j]] ? "HIGH" : "LOW");
101	        }
102	
103	      printf("\n");
104	    }
105	
106	  printf("\n");
107	  fflush(stdout);
108	}
109	
110	/** @brief 把 mask 内引脚写到指定电平。 */
111	static void iowrite_apply(FAR bool *level, unsigned mask)
112	{
113	  size_t i;
114	
115	  for (i = 0; i < IOWRITE_COUNT; i++)
116	    {
117	      if ((mask & (1u << i)) != 0)
118	        {
119	          iowrite_cfg_out(&g_iowrite_pins[i], level[i]);
120	        }
121	    }
122	
123	  iowrite_print(level, mask);
124	}
125	
126	/** @brief 解析 pwr / gnss / all；失败返回 -1。 */
127	static int iowrite_parse_pin(FAR const char *s, unsigned *mask)
128	{
129	  if (s == NULL || mask == NULL)
130	    {
131	      return -1;
132	    }
133	
134	  if (strcmp(s, "pwr") == 0 || strcmp(s, "pa27") == 0 ||
135	      strcmp(s, "pwr_md") == 0)
136	    {
137	      *mask = (1u << IOWRITE_PIN_PWR);
138	      return 0;
139	    }
140	
141	  if (strcmp(s, "gnss") == 0 || strcmp(s, "pa43") == 0 ||
142	      strcmp(s, "gnss_pwr") == 0)
143	    {
144	      *mask = (1u << IOWRITE_PIN_GNSS);
145	      return 0;
146	    }
147	
148	  if (strcmp(s, "all") == 0)
149	    {
150	      *mask = (1u << IOWRITE_PIN_PWR) | (1u << IOWRITE_PIN_GNSS);
151	      return 0;
152	    }
153	
154	  return -1;
155	}
156	
157	/** @brief 解析 0/1/loop；失败返回 -1。 */
158	static int iowrite_parse_level(FAR const char *s, bool *high, bool *loop)
159	{
160	  if (s == NULL || high == NULL || loop == NULL)
161	    {
162	      return -1;
163	    }
164	
165	  if (strcmp(s, "loop") == 0)
166	    {
167	      *loop = true;
168	      return 0;
169	    }
170	
171	  if (strcmp(s, "0") == 0 || strcmp(s, "low") == 0)
172	    {
173	      *high = false;
174	      *loop = false;
175	      return 0;
176	    }
177	
178	  if (strcmp(s, "1") == 0 || strcmp(s, "high") == 0)
179	    {
180	      *high = true;
181	      *loop = false;
182	      return 0;
183	    }
184	
185	  return -1;
186	}
187	
188	/**
189	 * @brief test iowrite 子命令入口。
190	 * @param argc 参数个数。
191	 * @param argv 参数向量。
192	 * @return 成功/失败退出码。
193	 */
194	int test_iowrite_main(int argc, FAR char *argv[])
195	{
196	  bool level[IOWRITE_COUNT];
197	  size_t i;
198	  unsigned mask = (1u << IOWRITE_PIN_PWR);
199	  bool high = true;
200	  bool loop = false;
201	  FAR const char *level_arg = NULL;
202	
203	  for (i = 0; i < IOWRITE_COUNT; i++)
204	    {
205	      level[i] = true;
206	    }
207	
208	  if (argc > 1)
209	    {
210	      if (iowrite_parse_pin(argv[1], &mask) == 0)
211	        {
212	          level_arg = (argc > 2) ? argv[2] : NULL;
213	        }
214	      else
215	        {
216	          level_arg = argv[1];
217	        }
218	
219	      if (level_arg != NULL &&
220	          iowrite_parse_level(level_arg, &high, &loop) != 0)
221	        {
222	          iowrite_usage();
223	          return EXIT_FAILURE;
224	        }
225	    }
226	
227	  for (i = 0; i < IOWRITE_COUNT; i++)
228	    {
229	      if ((mask & (1u << i)) != 0)
230	        {
231	          level[i] = high;
232	        }
233	    }
234	
235	  printf("test iowrite: PWR_MD PA27 (HIGH=FPWM, LOW=PFM); "
236	         "GNSS_PWR PA43"
237	#ifdef CONFIG_BOARD_L96_GNSS_PWR_ACTIVE_HIGH
238	         " (HIGH=module on).\n");
239	#else
240	         " (LOW=module on, active-low).\n");
241	#endif
242	  fflush(stdout);
243	
244	  iowrite_apply(level, mask);
245	
246	  if (!loop)
247	    {
248	      return EXIT_SUCCESS;
249	    }
250	
251	  for (; ; )
252	    {
253	      usleep(IOWRITE_TOGGLE_US);
254	      for (i = 0; i < IOWRITE_COUNT; i++)
255	        {
256	          if ((mask & (1u << i)) != 0)
257	            {
258	              level[i] = !level[i];
259	            }
260	        }
261	
262	      iowrite_apply(level, mask);
263	    }
264	
265	  return 0;
266	}
