2	 * vendor/my_vendor/boards/sf32lb52/my_vendor/test/test_uart2loop.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * USART2 (/dev/ttyS0) loopback self-test for GNSS wiring debug.
7	 * Hardware: PA31 = TX, PA32 = RX (see bsp_pinmux.c).
8	 *
9	 * Usage:
10	 *   test uart2loop              loopback 10 times (default)
11	 *   test uart2loop <count>      loopback count times
12	 *   test uart2loop <count> <baud>  loopback at baud (e.g. 115200)
13	 *   test uart2loop listen       RX-only sniffer @ 9600 for 15 s
14	 *   test uart2loop listen <baud> [sec]
15	 *
16	 * Loopback: short PA31 (TX) to PA32 (RX) with a jumper, then run the test.
17	 * Without jumper the test should FAIL (proves you are not reading local echo).
18	 ****************************************************************************/
19	
20	#include <nuttx/config.h>
21	
22	#if defined(CONFIG_BSP_USING_UART2)
23	
24	#include <stdbool.h>
25	#include <errno.h>
26	#include <fcntl.h>
27	#include <poll.h>
28	#include <stdio.h>
29	#include <stdlib.h>
30	#include <string.h>
31	#include <time.h>
32	#include <unistd.h>
33	
34	#ifdef CONFIG_BOARD_L96_GNSS
35	#  define UART2LOOP_DEVPATH   CONFIG_BOARD_L96_GNSS_DEVPATH
36	#  define UART2LOOP_BAUD_DEF  CONFIG_BOARD_L96_GNSS_BAUD
37	#else
38	#  define UART2LOOP_DEVPATH   "/dev/ttyS0"
39	#  define UART2LOOP_BAUD_DEF  9600
40	#endif
41	
42	#define UART2LOOP_UART_NUM        2
43	#define UART2LOOP_DEFAULT_COUNT   10
44	#define UART2LOOP_POLL_MS         100
45	#define UART2LOOP_LISTEN_SEC      15
