67	static void uart2loop_drain(int fd)
68	{
69	  char dump[64];
70	  struct pollfd pfd;
71	  ssize_t n;
72	
73	  for (; ; )
74	    {
75	      pfd.fd     = fd;
76	      pfd.events = POLLIN;
77	      if (poll(&pfd, 1, 0) <= 0)
78	        {
79	          break;
80	        }
81	
82	      n = read(fd, dump, sizeof(dump));
83	      if (n <= 0)
84	        {
85	          break;
86	        }
87	    }
88	}
