146	static int uart2loop_round(int fd, int round, int count, bool verbose)
147	{
148	  static const char tx[] = "UART2_LOOP_42_OK\r\n";
149	  char rx[sizeof(tx)];
150	  ssize_t nw;
151	  int nr;
152	  bool match;
153	
154	  uart2loop_drain(fd);
155	
156	  nw = write(fd, tx, strlen(tx));
157	  if (nw != (ssize_t)strlen(tx))
158	    {
159	      printf("[%d/%d] FAIL TX write nw=%zd errno=%d\n", round, count, nw, errno);
160	      return -1;
161	    }
162	
163	  usleep(50 * 1000);
164	
165	  memset(rx, 0, sizeof(rx));
166	  nr = uart2loop_read_bytes(fd, rx, strlen(tx), UART2LOOP_RX_TIMEOUT_MS);
167	  if (nr <= 0)
168	    {
169	      printf("[%d/%d] FAIL RX timeout (%d ms), got %d bytes\n",
170	             round, count, UART2LOOP_RX_TIMEOUT_MS, nr);
171	      return -1;
172	    }
173	
174	  match = (nr == (int)strlen(tx) && memcmp(rx, tx, strlen(tx)) == 0);
175	  if (match)
176	    {
177	      printf("[%d/%d] PASS loopback (%d bytes match)\n", round, count, nr);
178	      return 0;
179	    }
180	
181	  printf("[%d/%d] FAIL mismatch TX (%zu): %s", round, count, strlen(tx), tx);
182	  printf("[%d/%d] FAIL mismatch RX (%d): ", round, count, nr);
183	  uart2loop_print_rx(rx, nr);
184	  if (verbose)
185	    {
186	      printf("test uart2loop: round %d data dump above\n", round);
187	    }
188	
189	  return -1;
190	}
