192	static int uart2loop_run_loopback(int fd, int baud, int count)
193	{
194	  int round;
195	  int pass = 0;
196	
197	  printf("test uart2loop: USART2 %s @ %d baud x%d rounds\n",
198	         UART2LOOP_DEVPATH, baud, count);
199	  printf("test uart2loop: short PA31(TX) <-> PA32(RX) for external loopback\n");
200	  uart2loop_flush_stdout();
201	
202	  for (round = 1; round <= count; round++)
203	    {
204	      if (uart2loop_round(fd, round, count, round == 1) == 0)
