210	        {
211	          usleep(UART2LOOP_ROUND_DELAY_US);
212	        }
213	
214	      uart2loop_flush_stdout();
215	    }
216	
217	  printf("test uart2loop: summary %d/%d PASS\n", pass, count);
218	  return (pass == count) ? EXIT_SUCCESS : EXIT_FAILURE;
