221	static int uart2loop_run_listen(int fd, int baud, int sec)
222	{
223	  char ch;
224	  struct pollfd pfd;
225	  time_t deadline;
226	  time_t last_hb;
227	  time_t now;
228	  unsigned long bytes = 0;
229	  ssize_t n;
230	
231	  printf("test uart2loop: listen on %s @ %d baud for %d s (RX only)\n",
232	         UART2LOOP_DEVPATH, baud, sec);
233	  printf("test uart2loop: connect GNSS or loopback jumper, Ctrl+C to abort\n");
234	  uart2loop_flush_stdout();
235	
236	  uart2loop_drain(fd);
237	  deadline = time(NULL) + sec;
238	  last_hb  = time(NULL);
239	
240	  while ((now = time(NULL)) <= deadline)
241	    {
242	      pfd.fd     = fd;
243	      pfd.events = POLLIN;
244	      if (poll(&pfd, 1, UART2LOOP_POLL_MS) <= 0)
245	        {
246	          if (now - last_hb >= 3)
247	            {
248	              printf("test uart2loop: listen... %lu bytes\n", bytes);
249	              uart2loop_flush_stdout();
250	              last_hb = now;
251	            }
252	
253	          continue;
254	        }
255	
256	      n = read(fd, &ch, 1);
257	      if (n <= 0)
258	        {
259	          continue;
260	        }
261	
262	      bytes++;
263	      if (ch == '\n')
264	        {
265	          printf("\n");
266	        }
267	      else if (ch == '\r')
268	        {
269	          /* skip */
270	        }
271	      else if (ch >= 0x20 && ch < 0x7f)
272	        {
273	          putchar(ch);
274	        }
275	      else
276	        {
277	          printf("<%02x>", (unsigned char)ch);
278	        }
279	
280	      uart2loop_flush_stdout();
281	    }
282	
283	  printf("\ntest uart2loop: listen done, %lu bytes\n", bytes);
284	  return (bytes > 0) ? EXIT_SUCCESS : EXIT_FAILURE;
285	}
