720	        }
721	
722	      /* In any event, we do have to configure for interrupt driven mode of
723	       * operation.  Attach the hardware IRQ(s). Hmm.. should shutdown() the
724	       * the device in the rare case that uart_attach() fails, tmp==1, and
725	       * this is not the console.
726	       */
727	
728	      ret = uart_attach(dev);
729	      if (ret < 0)
730	        {
731	          if (!dev->isconsole)
732	            {
733	              uart_shutdown(dev);
734	            }
735	
736	          uart_spinunlock(dev, false, flags);
737	          goto errout_with_lock;
738	        }
739	
740	#ifdef CONFIG_SERIAL_RXDMA
741	      /* Notify DMA that there is free space in the RX buffer */
742	
743	      uart_dmarxfree(dev);
744	#endif
745	
746	      /* Enable the RX interrupt */
747	
748	      uart_enablerxint(dev);
749	      uart_spinunlock(dev, false, flags);
750	    }
751	
752	  /* Save the new open count on success */
753	
754	  dev->open_count = tmp;
755	
756	errout_with_lock:
757	  nxmutex_unlock(&dev->closelock);
758	  return ret;
759	}
