761	/****************************************************************************
762	 * Name: uart_close
763	 *
764	 * Description:
765	 *   This routine is called when the serial port gets closed.
766	 *   It waits for the last remaining data to be sent.
767	 *
768	 ****************************************************************************/
769	
770	static int uart_close(FAR struct file *filep)
771	{
772	  FAR struct inode *inode = filep->f_inode;
773	  FAR uart_dev_t   *dev   = inode->i_private;
774	  irqstate_t        flags;
775	
776	  /* Get exclusive access to the close semaphore (to synchronize open/close
777	   * operations.
778	   * NOTE: that we do not let this wait be interrupted by a signal.
779	   * Technically, we should, but almost no one every checks the return value
780	   * from close() so we avoid a potential memory leak by ignoring signals in
781	   * this case.
782	   */
783	
784	  nxmutex_lock(&dev->closelock);
785	  if (dev->open_count > 1)
786	    {
787	      dev->open_count--;
788	      nxmutex_unlock(&dev->closelock);
789	      return OK;
790	    }
791	
792	  /* There are no more references to the port */
793	
794	  dev->open_count = 0;
795	
796	  /* Stop accepting input */
797	
798	  uart_disablerxint(dev);
799	
800	  /* Prevent blocking if the device is opened with O_NONBLOCK */
801	
802	  if ((filep->f_oflags & O_NONBLOCK) == 0)
803	    {
804	      /* Now we wait for the transmit buffer(s) to clear */
805	
806	      uart_tcdrain(dev, false, 4 * TICK_PER_SEC);
807	    }
808	
809	  /* Free the IRQ and disable the UART */
810	
811	  flags = uart_spinlock(dev, false);
812	  uart_detach(dev);                  /* Detach interrupts */
813	
814	  /* Check for the serial console UART */
815	
816	  if (!dev->isconsole)
817	    {
818	      uart_shutdown(dev);            /* Disable the UART */
819	    }
820	
821	  uart_spinunlock(dev, false, flags);
822	
823	  /* Wake up read and poll functions */
824	
825	  uart_datareceived(dev);
826	
827	  /* We need to re-initialize the semaphores if this is the last close
828	   * of the device, as the close might be caused by pthread_cancel() of
829	   * a thread currently blocking on any of them.
830	   */
831	
832	  uart_reset_sem(dev);
833	
834	  if (dev->unlinked)
835	    {
836	      nxmutex_unlock(&dev->closelock);
837	      nxmutex_destroy(&dev->xmit.lock);
838	      nxmutex_destroy(&dev->recv.lock);
839	      nxmutex_destroy(&dev->closelock);

2540	    return;
2541	  }
2542	
2543	  if (id == MINMEA_SENTENCE_ZDA) {
2544	    struct minmea_sentence_zda zda;
2545	
2546	    if (minmea_parse_zda(&zda, line)) {
2547	      gnss_remember_date(&zda.date);
2548	      gnss_try_set_utc(acc, &zda.date, &zda.time);
2549	      gnss_publish(acc);
2550	    }
2551	  }
2552	}
