2554	static void *gnss_thread(void *arg)
2555	{
2556	  myvendor_sys_gnss_t acc;
2557	  char line[GNSS_LINE_MAX];
2558	  char rx[GNSS_RX_BATCH];
2559	  size_t cnt = 0;
2560	  bool discard = false;
2561	  int fd = -1;
2562	  int rxn = 0;
2563	  int rxi = 0;
2564	  uint8_t rx_st = 0;
2565	  uint8_t ubx_hdr[4];
2566	  uint8_t ubx_hdr_i = 0;
2567	  uint16_t ubx_len = 0;
2568	  uint16_t ubx_i = 0;
2569	  uint8_t ubx_ck = 0;
2570	  uint8_t ubx_got_cka = 0;
2571	  uint32_t last_nmea_ms;
2572	  bool had_valid = false;
2573	  uint32_t first_fix_ms = 0;
2574	  bool pkt_open = false;
2575	
2576	  (void)arg;
2577	  memset(&acc, 0, sizeof(acc));
2578	  g_boot_ms = gnss_now_ms();
2579	  last_nmea_ms = g_boot_ms;
2580	  g_nmea_life_ms = last_nmea_ms;
2581	  g_gnss_pid = getpid();
2582	  g_gnss_stop = false;
2583	  g_idle_parked = false;
2584	  gnss_recover_begin();
2585	  gnss_heartbeat();
2586	#ifndef CONFIG_DISABLE_PTHREAD
2587	  pthread_setname_np(pthread_self(), "gnss");
2588	#endif
2589	
2590	  for (;;) {
2591	    char ch;
2592	    int rc;
2593	    uint8_t b;
2594	    uint32_t now;
2595	    uint32_t silent;
2596	
2597	    gnss_heartbeat();
2598	    if (g_gnss_stop) {
2599	      gnss_fd_release(&fd);
2600	      break;
2601	    }
2602	
2603	    /* USART2 对齐 NSH：先 open，之后一直 poll。低功耗只切模组 VCC。 */
2604	    if (fd < 0) {
2605	      bool cycle = false;
2606	
2607	      if (g_idle_sleep) {
2608	        sf32lb52_l96_uart_pins();
2609	      } else {
2610	        cycle = (g_uart_fails >= GNSS_PWR_FAILS);
2611	        gnss_module_ensure();
2612	        if (cycle) {
2613	          gnss_module_power_cycle();
2614	          g_uart_fails = 0;
2615	        } else {
2616	          sf32lb52_l96_uart_pins();
2617	        }
2618	      }
2619	
2620	      fd = gnss_open();
2621	      g_uart_fd = fd;
2622	      if (fd < 0) {
2623	        g_uart_fails++;
2624	        syslog(LOG_WARNING, "gnss: open %s failed errno=%d fail=%u\n",
2625	               CONFIG_BOARD_L96_GNSS_DEVPATH, errno,
2626	               (unsigned)g_uart_fails);
2627	        usleep(GNSS_RETRY_MS * 1000);
2628	        continue;
2629	      }
2630	
2631	      if (g_idle_sleep) {
2632	        gnss_module_park();
2633	        g_eph_injected = false;
2634	        g_idle_parked = true;
2635	      } else {
2636	        gnss_reconfig_after_vcc(fd, cycle);
2637	      }
2638	
2639	      syslog(LOG_INFO, "gnss: open %s @ %d%s (" GNSS_MOD_PN ", UART hold)\n",
2640	             CONFIG_BOARD_L96_GNSS_DEVPATH, CONFIG_BOARD_L96_GNSS_BAUD,
2641	             g_idle_parked ? " idle" : (cycle ? " (pwr)" : ""));
2642	      goto rx_fresh;
2643	    }
2644	
2645	    if (g_idle_sleep) {
2646	      if (!g_idle_parked) {
2647	        GNSS_LOG("idle sleep park fd=%d silent=%u eph=%d",
2648	                 fd, (unsigned)gnss_elapsed_ms(gnss_now_ms(), g_nmea_life_ms),
2649	                 g_eph_busy ? 1 : 0);
2650	        gnss_module_park();
2651	        g_eph_injected = false;
2652	        g_idle_parked = true;
2653	        syslog(LOG_INFO, "gnss: idle sleep, " GNSS_MOD_PN
2654	               " VCC off PA43 (USART2 hold like NSH)\n");
2655	        goto rx_fresh;
2656	      }
2657	    } else if (g_idle_parked) {
2658	      unsigned on_ms = (unsigned)CONFIG_BOARD_L96_GNSS_PWR_DELAY_MS;
2659	
2660	      g_idle_parked = false;
2661	      syslog(LOG_INFO, "gnss: idle wake, " GNSS_MOD_PN
2662	             " VCC on PA43 (settle %u ms, USART2 hold)\n", on_ms);
2663	      GNSS_LOG("idle wake hold=%d eph_inj=%d fails=%u fd=%d",
2664	               g_wake_hold_ms != 0 ? 1 : 0,
2665	               g_eph_injected ? 1 : 0,
2666	               (unsigned)g_uart_fails, fd);
2667	      sf32lb52_l96_uart_pins();
2668	      (void)sf32lb52_l96_power(true);
2669	      usleep(on_ms * 1000u);
2670	      g_mod_pwr = true;
2671	      gnss_reconfig_after_vcc(fd, false);
2672	      goto rx_fresh;
2673	    }
2674	
2675	    if (g_diag_kick) {
2676	      g_diag_kick = false;
2677	      if (!g_idle_parked) {
2678	        gnss_recover_begin();
2679	        syslog(LOG_WARNING,
2680	               "gnss: diag kick, " GNSS_MOD_PN " VCC cycle (UART open)\n");
2681	        if ((g_uart_fails + 1u) >= GNSS_PWR_FAILS) {
2682	          g_eph_hold = true;
2683	        }
2684	
2685	        gnss_vcc_recover(fd, true);
2686	        goto rx_fresh;
2687	      }
2688	    }
2689	
2690	    goto rx_run;
2691	
2692	rx_fresh:
2693	    cnt = 0;
2694	    discard = false;
2695	    rx_st = 0;
2696	    rxn = 0;
2697	    rxi = 0;
2698	    pkt_open = false;
2699	    ubx_hdr_i = 0;
2700	    ubx_len = 0;
2701	    ubx_i = 0;
2702	    ubx_ck = 0;
2703	    last_nmea_ms = gnss_now_ms();
2704	    g_nmea_life_ms = last_nmea_ms;
2705	
2706	rx_run:
2707	    if (!g_idle_parked) {
2708	      gnss_eph_boot_try(fd);
2709	      gnss_dbd_try_start(fd, had_valid, first_fix_ms);
2710	      gnss_dbd_tick();
2711	      gnss_dyn_apply(fd, false);
2712	
2713	      now = gnss_now_ms();
2714	      last_nmea_ms = g_nmea_life_ms;
2715	      silent = gnss_elapsed_ms(now, last_nmea_ms);
2716	      gnss_link_report(fd, rx_st, silent);
2717	      {
2718	        uint32_t quiet_lim = GNSS_SILENCE_MS;
2719	
2720	        if (gnss_hold_unlocked(now) || g_eph_busy || g_dbd_run) {
2721	          quiet_lim = GNSS_EPH_GRACE_MS;
2722	        } else {
2723	          pthread_mutex_lock(&g_lock);
2724	          if (gnss_eph_grace_locked(now)) {
2725	            quiet_lim = GNSS_EPH_GRACE_MS;
2726	          }
2727	
2728	          pthread_mutex_unlock(&g_lock);
2729	        }
2730	
2731	        if (silent > quiet_lim) {
2732	          if (g_dbd_run) {
2733	            gnss_dbd_abort();
2734	          }
2735	
2736	          if ((g_uart_fails + 1u) >= GNSS_PWR_FAILS) {
2737	            g_eph_hold = true;
2738	          }
2739	
2740	          syslog(LOG_WARNING,
2741	                 "gnss: no publish for %u ms, " GNSS_MOD_PN
2742	                 " VCC cycle (fail=%u, UART open)\n",
2743	                 (unsigned)silent, (unsigned)(g_uart_fails + 1u));
2744	          GNSS_LOG("vcc silence quiet_lim=%u eph=%d dbd=%d recov=%d",
2745	                   (unsigned)quiet_lim, g_eph_busy ? 1 : 0,
2746	                   g_dbd_run ? 1 : 0, g_recovering ? 1 : 0);
2747	          gnss_vcc_recover(fd, false);
2748	          goto rx_fresh;
2749	        }
2750	      }
2751	    }
2752	
2753	    if (rxi >= rxn) {
2754	      rc = gnss_read_some(fd, rx, GNSS_RX_BATCH, 200);
2755	      if (rc < 0) {
2756	        if (g_idle_parked) {
2757	          GNSS_LOG("idle uart read %d errno=%d (USART2 hold)", rc, errno);
2758	          continue;
2759	        }
2760	
2761	        syslog(LOG_WARNING,
2762	               "gnss: uart read %d, " GNSS_MOD_PN " VCC cycle (fail=%u)\n",
2763	               rc, (unsigned)(g_uart_fails + 1u));
2764	        GNSS_LOG("vcc read rc=%d errno=%d poll_run=%u",
2765	                 rc, errno, (unsigned)g_poll_to_run);
2766	        gnss_vcc_recover(fd, g_diag_kick);
2767	        goto rx_fresh;
2768	      }
2769	
2770	      if (rc == 0) {
2771	        if (!g_idle_parked) {
2772	          pkt_open = false;
2773	          gnss_dbd_tick();
2774	          if (gnss_eph_try_reload(fd)) {
2775	            rx_st = 0;
2776	            cnt = 0;
2777	            discard = false;
2778	            last_nmea_ms = gnss_now_ms();
2779	            g_nmea_life_ms = last_nmea_ms;
2780	          }
2781	        }
2782	
2783	        continue;
2784	      }
2785	
2786	      rxn = rc;
2787	      rxi = 0;
2788	      if (g_idle_parked) {
2789	        /* 模组 VCC 已关：丢掉浮空 RX，UART 仍按 NSH 方式一直收。 */
2790	        rxi = rxn;
2791	        continue;
2792	      }
2793	
2794	      if (!pkt_open) {
2795	        pkt_open = true;
2796	        pthread_mutex_lock(&g_lock);
2797	        gnss_rx_note(gnss_now_ms());
2798	        pthread_mutex_unlock(&g_lock);
2799	      }
2800	    }
2801	
2802	    ch = rx[rxi++];
2803	
2804	    b = (uint8_t)ch;
2805	
2806	    /* 0 idle  1 nmea  2 ubx-wait-62  3 ubx-hdr  4 ubx-pay  5 ubx-ck */
2807	    if (rx_st == 0) {
2808	      if (ch == '$') {
2809	        rx_st = 1;
2810	        cnt = 0;
2811	        discard = false;
2812	        line[cnt++] = ch;
2813	      } else if (b == 0xb5) {
2814	        rx_st = 2;
2815	      } else {
2816	        gnss_link_add(&g_link.junk);
2817	      }
2818	
2819	      continue;
2820	    }
2821	
2822	    if (rx_st == 1) {
2823	      if (ch == '\r') {
2824	        continue;
2825	      }
2826	
2827	      if (ch == '\n') {
2828	        /* 只有 gnss_publish 才算活着。任意 $ 行（坏校验 / TXT）若在
2829	         * 这里清 fail，垃圾句会掐死断电恢复，UI 就一直「无数据」。 */
2830	        if (discard) {
2831	          gnss_link_add(&g_link.nmea_bad);
2832	        } else if (cnt > 0) {
2833	          line[cnt] = '\0';
2834	          gnss_link_add(&g_link.nmea);
2835	          if (!g_link_got_nmea) {
2836	            g_link_got_nmea = true;
2837	            syslog(LOG_INFO, "gnss: first nmea %.8s\n", line);
2838	          }
2839

380	
381	  interactive_expire_locked();
382	
383	  if ((g_holds & SF32LB_DVFS_HOLD_FLOOR) != 0)
384	    {
385	      return SF32LB_DVFS_MHZ_240;
386	    }
387	
388	#ifdef CONFIG_SCHED_CPULOAD_NONE
389	  target = g_holds ? SF32LB_DVFS_MHZ_240 : SF32LB_DVFS_MHZ_144;
390	#else
391	  target = g_gov_mhz;
392	#endif
393	
394	  if (g_interactive_active && target < interactive_mhz())
395	    {
396	      target = interactive_mhz();
397	    }
398	
399	  return target;
400	}
