449	/**
450	 * @brief 将仲裁后的目标档位应用到硬件。
451	 *
452	 * @return 0 表示成功或无需切换，-EIO 表示 HAL 切频失败。
453	 * @note 调用者必须持有 g_lock。
454	 */
455	static int apply_locked(void)
456	{
457	  irqstate_t flags;
458	  HAL_StatusTypeDef st;
459	  uint32_t want;
460	  uint32_t dll2;
461	
462	  if (!g_hw_ready)
463	    {
464	      return 0;
465	    }
466	
467	  want = target_mhz_locked();
468	  if (want == g_applied_mhz)
469	    {
470	      return 0;
471	    }
472	
473	  flags = enter_critical_section();
474	  SCB_InvalidateICache();
475	  st = HAL_RCC_HCPU_ConfigHCLK(want);
476	  leave_critical_section(flags);
477	
478	  if (st != HAL_OK)
479	    {
480	      syslog(LOG_ERR,
481	             "dvfs: ConfigHCLK(%u) st=%d holds=0x%x idle=%u gov=%u "
482	             "boost=%u dll2=%lu\n",
483	             (unsigned)want, (int)st, (unsigned)g_holds,
484	             (unsigned)g_idle_pct, (unsigned)g_gov_mhz,
485	             (unsigned)(g_interactive_active ? interactive_mhz() : 0),
486	             (unsigned long)HAL_RCC_HCPU_GetDLL2Freq());
487	      return -EIO;
488	    }
489	
490	  g_applied_mhz = want;
491	  reclock_peripherals();
492	  dll2 = HAL_RCC_HCPU_GetDLL2Freq();
493	  syslog(LOG_INFO,
494	         "dvfs: HCLK=%u MHz holds=0x%x force=%u idle=%u gov=%u "
495	         "boost=%u dll2=%lu\n",
496	         (unsigned)g_applied_mhz, (unsigned)g_holds,
497	         (unsigned)g_force_mhz, (unsigned)g_idle_pct,
498	         (unsigned)g_gov_mhz,
499	         (unsigned)(g_interactive_active ? interactive_mhz() : 0),
500	         (unsigned long)dll2);
501	  return 0;
502	}
