504	/**
505	 * @brief 将 hold 位图转换为便于诊断的名称列表。
506	 *
507	 * @param buf 输出缓冲区。
508	 * @param n 输出缓冲区长度。
509	 * @param holds hold 位图。
510	 */
511	static void holds_put(char *buf, size_t n, uint32_t holds)
512	{
513	  size_t used = 0;
514	  unsigned i;
515	  static const struct
516	  {
517	    uint32_t bit;
518	    const char *name;
519	  } names[] =
520	    {
521	      { SF32LB_DVFS_HOLD_BOOT,   "boot" },
522	      { SF32LB_DVFS_HOLD_AWAKE,  "awake" },
523	      { SF32LB_DVFS_HOLD_MAP,    "map" },
524	      { SF32LB_DVFS_HOLD_CHARGE, "charge" },
525	      { SF32LB_DVFS_HOLD_OFFING, "off" },
526	    };
527	
528	  if (n == 0)
529	    {
530	      return;
531	    }
532	
533	  buf[0] = '\0';
534	  if (holds == 0)
535	    {
536	      (void)snprintf(buf, n, "-");
537	      return;
538	    }
539	
540	  for (i = 0; i < sizeof(names) / sizeof(names[0]); i++)
541	    {
542	      int w;
543	
544	      if ((holds & names[i].bit) == 0)
545	        {
546	          continue;
547	        }
548	
549	      w = snprintf(buf + used, n - used, "%s%s",
550	                   used ? "," : "", names[i].name);
551	      if (w < 0 || (size_t)w >= n - used)
552	        {
553	          return;
554	        }
555	
556	      used += (size_t)w;
557	    }
558	}
