560	/**
561	 * @brief LPWORK 周期负载采样与调频入口。
562	 *
563	 * @param arg work queue 参数，当前未使用。
564	 */
565	static void gov_worker(FAR void *arg)
566	{
567	  (void)arg;
568	
569	  nxmutex_lock(&g_lock);
570	  if (g_hw_ready)
571	    {
572	      gov_update_load_locked(idle_pct_now());
573	      charge_hold_locked();
574	      (void)apply_locked();
575	    }
576	
